#!/usr/bin/env bash
# Run each hand-written edge-case dataset through the binary and diff stdout
# against the committed expected output.
#
#   tests/run_edge_cases.sh [binary [extra args...]]   (default ./fpgrowth)
#
# Extra arguments are passed to every run (e.g. --threads 3).
#
# Expected files were generated by independent brute-force enumeration
# (see tests/brute_force.py for the same algorithm).
set -u
cd "$(dirname "$0")/.."
BIN=${1:-./fpgrowth}
[ $# -gt 0 ] && shift
EXTRA=("$@")

# name  min_support   (data tests/edge_cases/<name>.dat, expected <name>.expected)
CASES="
empty               1
single_transaction  1
all_identical       5
none_frequent       2
all_frequent        2
long_transaction    1
"

pass=0 fail=0
out=$(mktemp) err=$(mktemp)
trap 'rm -f "$out" "$err"' EXIT

while read -r name sup; do
    [ -z "$name" ] && continue
    dat=tests/edge_cases/$name.dat
    exp=tests/edge_cases/$name.expected
    "$BIN" "$dat" "$sup" ${EXTRA[@]+"${EXTRA[@]}"} >"$out" 2>"$err"
    rc=$?
    if [ $rc -ne 0 ] || grep -q "Sanitizer" "$err"; then
        echo "FAIL $name: exit code $rc (binary $BIN, min_support $sup)"
        cat "$err"
        fail=$((fail + 1))
    elif ! diff -u "$exp" "$out" >/dev/null; then
        echo "FAIL $name: output differs from $exp (binary $BIN, min_support $sup)"
        diff -u "$exp" "$out" | head -20
        fail=$((fail + 1))
    else
        echo "PASS $name"
        pass=$((pass + 1))
    fi
done <<EOF
$CASES
EOF

echo "edge cases ($BIN${EXTRA[*]+ ${EXTRA[*]}}): $pass passed, $fail failed"
[ "$fail" -eq 0 ]
